#!/usr/bin/env node
import fs from 'node:fs';
import path from 'node:path';

const ROOT = process.cwd();
const DRY_RUN = process.argv.includes('--dry-run');
const RESTORE = process.argv.includes('--restore');
const PATCH_ID = 'expansion-gacha-skills-tools-google-v1';
const BACKUP_DIR = path.join(ROOT, '.patch-backups', PATCH_ID);
const MANIFEST = path.join(BACKUP_DIR, 'manifest.json');
const log = (...args) => console.log('[FIX]', ...args);
const normalize = (p) => p.split(path.sep).join('/');

function assertProjectRoot() {
  const settings = ['settings.gradle.kts', 'settings.gradle'].some(f => fs.existsSync(path.join(ROOT, f)));
  const app = fs.existsSync(path.join(ROOT, 'app'));
  if (!settings || !app) throw new Error('Execute esta fix na raiz do projeto Android (onde ficam settings.gradle.kts e app/).');
}

function mkdirp(dir) { if (!DRY_RUN) fs.mkdirSync(dir, { recursive: true }); }
function read(rel) { return fs.readFileSync(path.join(ROOT, rel), 'utf8'); }
function exists(rel) { return fs.existsSync(path.join(ROOT, rel)); }
function ensureParent(rel) { mkdirp(path.dirname(path.join(ROOT, rel))); }

let manifest = { patchId: PATCH_ID, created: [], modified: [] };
function loadManifest() {
  if (fs.existsSync(MANIFEST)) manifest = JSON.parse(fs.readFileSync(MANIFEST, 'utf8'));
}
function saveManifest() {
  if (DRY_RUN) return;
  mkdirp(BACKUP_DIR);
  fs.writeFileSync(MANIFEST, JSON.stringify(manifest, null, 2));
}
function backup(rel) {
  if (!exists(rel) || manifest.modified.includes(rel)) return;
  const target = path.join(BACKUP_DIR, rel);
  if (!DRY_RUN) {
    fs.mkdirSync(path.dirname(target), { recursive: true });
    fs.copyFileSync(path.join(ROOT, rel), target);
  }
  manifest.modified.push(rel);
}
function writeFile(rel, content) {
  const had = exists(rel);
  if (had && read(rel) === content) { log('sem mudança:', rel); return; }
  if (had) backup(rel); else if (!manifest.created.includes(rel)) manifest.created.push(rel);
  log(DRY_RUN ? 'criaria/atualizaria:' : 'gravando:', rel);
  if (!DRY_RUN) { ensureParent(rel); fs.writeFileSync(path.join(ROOT, rel), content.replace(/\r\n/g, '\n'), 'utf8'); }
}
function patchFile(rel, transform) {
  if (!exists(rel)) { log('AVISO: arquivo não encontrado:', rel); return false; }
  const before = read(rel);
  const after = transform(before);
  if (after === before) { log('sem mudança:', rel); return false; }
  writeFile(rel, after);
  return true;
}
function walk(dir, out = []) {
  if (!fs.existsSync(dir)) return out;
  for (const entry of fs.readdirSync(dir, { withFileTypes: true })) {
    if (entry.name === 'build' || entry.name === '.gradle' || entry.name === '.git') continue;
    const full = path.join(dir, entry.name);
    if (entry.isDirectory()) walk(full, out); else out.push(full);
  }
  return out;
}
function rel(full) { return normalize(path.relative(ROOT, full)); }
function addImport(src, importLine) {
  if (src.includes(importLine)) return src;
  const pkg = src.match(/^package\s+[^\n]+\n/m);
  if (!pkg) return src;
  const idx = pkg.index + pkg[0].length;
  return src.slice(0, idx) + '\n' + importLine + '\n' + src.slice(idx);
}
function matchingBrace(text, openIndex) {
  let depth = 0, inString = false, quote = '', escape = false, lineComment = false, blockComment = false;
  for (let i = openIndex; i < text.length; i++) {
    const c = text[i], n = text[i + 1];
    if (lineComment) { if (c === '\n') lineComment = false; continue; }
    if (blockComment) { if (c === '*' && n === '/') { blockComment = false; i++; } continue; }
    if (inString) { if (escape) { escape = false; continue; } if (c === '\\') { escape = true; continue; } if (c === quote) inString = false; continue; }
    if (c === '/' && n === '/') { lineComment = true; i++; continue; }
    if (c === '/' && n === '*') { blockComment = true; i++; continue; }
    if (c === '"' || c === "'") { inString = true; quote = c; continue; }
    if (c === '{') depth++;
    if (c === '}') { depth--; if (depth === 0) return i; }
  }
  return -1;
}
function functionBodyRange(src, name) {
  const re = new RegExp('fun\\s+' + name + '\\s*\\(');
  const m = re.exec(src); if (!m) return null;
  const open = src.indexOf('{', m.index + m[0].length); if (open < 0) return null;
  const close = matchingBrace(src, open); if (close < 0) return null;
  return { open, close };
}
function injectExpansionEntry(src) {
  if (src.includes('EXPANSION_HUB_INJECTED')) return src;
  let out = addImport(src, 'import br.com.usinagemmaster.feature.expansion.ExpansionHubDialog');
  let range = functionBodyRange(out, 'MachinesScreen');
  if (!range) { log('AVISO: não achei fun MachinesScreen para inserir atalho da expansão.'); return out; }
  const state = '\n    // EXPANSION_HUB_INJECTED\n    val expansionHubVisible = androidx.compose.runtime.saveable.rememberSaveable { androidx.compose.runtime.mutableStateOf(false) }\n';
  out = out.slice(0, range.open + 1) + state + out.slice(range.open + 1);
  range = functionBodyRange(out, 'MachinesScreen');
  const body = out.slice(range.open, range.close);
  const lazyPosLocal = body.indexOf('LazyColumn(');
  const columnPosLocal = lazyPosLocal >= 0 ? lazyPosLocal : body.indexOf('Column(');
  if (columnPosLocal >= 0) {
    const callPos = range.open + columnPosLocal;
    const contentBrace = out.indexOf('{', callPos);
    if (contentBrace > 0 && contentBrace < range.close) {
      const entry = lazyPosLocal >= 0
        ? '\n            item(key = "expansion_hub_entry") {\n                androidx.compose.material3.Button(onClick = { expansionHubVisible.value = true }) {\n                    androidx.compose.material3.Text("⚙ Evolução • Roleta • Skills")\n                }\n            }\n'
        : '\n            androidx.compose.material3.Button(onClick = { expansionHubVisible.value = true }) {\n                androidx.compose.material3.Text("⚙ Evolução • Roleta • Skills")\n            }\n';
      out = out.slice(0, contentBrace + 1) + entry + out.slice(contentBrace + 1);
    }
  } else {
    log('AVISO: MachinesScreen sem LazyColumn/Column detectável; dialog foi integrado, mas sem botão automático.');
  }
  range = functionBodyRange(out, 'MachinesScreen');
  const dialog = '\n    if (expansionHubVisible.value) {\n        ExpansionHubDialog(onDismiss = { expansionHubVisible.value = false })\n    }\n';
  out = out.slice(0, range.close) + dialog + out.slice(range.close);
  return out;
}
function patchFactoryResponsive(src) {
  let out = src;
  out = out.replace(
    'Modifier.fillMaxWidth().height(560.dp).padding(8.dp).background(',
    'Modifier.fillMaxWidth().height(if (androidx.compose.ui.platform.LocalConfiguration.current.screenWidthDp < 390) 472.dp else 540.dp).padding(8.dp).background('
  );
  out = out.replace('val cellHeight = 90.dp', 'val cellHeight = if (maxWidth < 390.dp) 76.dp else 86.dp');
  const anchor = '.width((cellWidth - 6.dp).coerceAtLeast(54.dp))';
  const idx = out.indexOf(anchor);
  if (idx >= 0) {
    const tail = out.slice(idx, idx + 400);
    const patchedTail = tail.replace('.height(82.dp)', '.height(if (maxWidth < 390.dp) 68.dp else 78.dp)');
    out = out.slice(0, idx) + patchedTail + out.slice(idx + tail.length);
  }
  return out;
}
function patchProductionEngine(src) {
  let out = addImport(src, 'import br.com.usinagemmaster.domain.expansion.ProductionModifiers');
  if (!out.includes('modifiers: ProductionModifiers')) {
    out = out.replace(
      /idleEmployeeIds:\s*Set<String>\s*=\s*emptySet\(\)\s*\n\s*\):\s*ProductionSnapshot\s*\{/,
      'idleEmployeeIds: Set<String> = emptySet(),\n        modifiers: ProductionModifiers = ProductionModifiers(),\n    ): ProductionSnapshot {'
    );
  }
  if (!out.includes('val expansionMachineMultiplier = modifiers.multiplierForMachine')) {
    out = out.replace(
      'val legendaryBonus = legendaryMachineMultiplier(employee.legendaryCode, machine.machineType)',
      'val legendaryBonus = legendaryMachineMultiplier(employee.legendaryCode, machine.machineType)\n        val expansionMachineMultiplier = modifiers.multiplierForMachine(machine.machineType)'
    );
    out = out.replace(
      'legendaryBonus * supportProductivityMultiplier',
      'legendaryBonus * supportProductivityMultiplier * expansionMachineMultiplier * modifiers.globalSpeedMultiplier'
    );
    out = out.replace(
      /supportQualityBonus\s*\n\s*\)\.roundToInt\(\)\.coerceIn\(1, 100\)/,
      'supportQualityBonus +\n            modifiers.qualityBonus\n        ).roundToInt().coerceIn(1, 100)'
    );
    out = out.replace(/powerKw\s*=\s*definition\.powerKw\s*,/, 'powerKw = definition.powerKw * modifiers.energyMultiplier,');
  }
  return out;
}
function patchGameRepository(src) {
  let out = addImport(src, 'import br.com.usinagemmaster.data.preferences.ExpansionRepository');
  out = addImport(out, 'import br.com.usinagemmaster.domain.expansion.ExpansionState');
  if (!out.includes('private val expansionRepository: ExpansionRepository')) {
    out = out.replace(
      /private val gamePreferences:\s*GamePreferences\s*\n\s*\)/,
      'private val gamePreferences: GamePreferences,\n    private val expansionRepository: ExpansionRepository\n)'
    );
  }
  if (!out.includes('gamePreferences.workforce, expansionRepository.state')) {
    out = out.replace(
      /override fun production\(\): Flow<ProductionSnapshot> = combine\(\s*machineDao\.observeAll\(\), employeeDao\.observeAll\(\), gamePreferences\.workforce\s*\) \{ machines, employees, workforce -> calculateProduction\(machines, employees, workforce\) \}/s,
      'override fun production(): Flow<ProductionSnapshot> = combine(\n        machineDao.observeAll(), employeeDao.observeAll(), gamePreferences.workforce, expansionRepository.state\n    ) { machines, employees, workforce, expansion -> calculateProduction(machines, employees, workforce, expansion) }'
    );
  }
  if (!out.includes('expansion: ExpansionState = ExpansionState()')) {
    out = out.replace(
      /workforce:\s*WorkforceState\s*=\s*WorkforceState\(\)\s*\n\s*\):\s*ProductionSnapshot\s*\{/,
      'workforce: WorkforceState = WorkforceState(),\n        expansion: ExpansionState = ExpansionState()\n    ): ProductionSnapshot {'
    );
  }
  if (!out.includes('modifiers = expansion.productionModifiers()')) {
    out = out.replace(
      /idleEmployeeIds\s*=\s*idleIds\s*\n\s*\)/,
      'idleEmployeeIds = idleIds,\n        modifiers = expansion.productionModifiers()\n    )'
    );
  }
  // Simulação offline/normal lê a expansão uma única vez por fechamento.
  if (!out.includes('val expansion = expansionRepository.snapshot()')) {
    out = out.replace(
      /val workforce = gamePreferences\.workforce\.first\(\)\s*\n(\s*)val snapshot = calculateProduction\(machines, employees, workforce\)/,
      'val workforce = gamePreferences.workforce.first()\n$1val expansion = expansionRepository.snapshot()\n$1val snapshot = calculateProduction(machines, employees, workforce, expansion)'
    );
  }
  out = out.replace(
    'calculateProduction(machineDao.getAll(), employeeDao.getAll(), gamePreferences.workforce.first())',
    'calculateProduction(machineDao.getAll(), employeeDao.getAll(), gamePreferences.workforce.first(), expansionRepository.snapshot())'
  );
  // Ferramenta específica por contrato: velocidade/qualidade e consumo ao concluir.
  if (!out.includes('val toolEffect = expansion.toolEffectForContract(contract.id)')) {
    out = out.replace(
      'val qualityGap = contract.requiredQuality - snapshot.averageQuality',
      'val toolEffect = expansion.toolEffectForContract(contract.id)\n            val effectiveQuality = (snapshot.averageQuality + toolEffect.qualityBonus).coerceIn(0, 100)\n            val qualityGap = contract.requiredQuality - effectiveQuality'
    );
    out = out.replace(
      'val acceptedAvailable = (productionMilli * qualityFactor).toLong()',
      'val acceptedAvailable = (productionMilli * qualityFactor * toolEffect.speedMultiplier).toLong()'
    );
    out = out.replace(
      'val rawConsumed = if (qualityFactor <= 0.0) productionMilli else kotlin.math.ceil(applied / qualityFactor).toLong()',
      'val effectiveFactor = qualityFactor * toolEffect.speedMultiplier\n            val rawConsumed = if (effectiveFactor <= 0.0) productionMilli else kotlin.math.ceil(applied / effectiveFactor).toLong()'
    );
    out = out.replace(
      'if (paidNow) contractRewards += contract.rewardCents\n\n            completedContracts++',
      'if (paidNow) contractRewards += contract.rewardCents\n            expansionRepository.consumeBoundTool(contract.id)\n\n            completedContracts++'
    );
  }
  // Requisitos de nível/skills para aceitar contrato.
  if (!out.includes('val contractAccess = expansionRepository.contractAccess')) {
    out = out.replace(
      'require(contract.status == ContractStatus.AVAILABLE.name) { "Contrato indisponível" }',
      'require(contract.status == ContractStatus.AVAILABLE.name) { "Contrato indisponível" }\n        val companyForContract = companyDao.get() ?: error("Empresa não inicializada")\n        val contractAccess = expansionRepository.contractAccess(contract.difficulty, companyForContract.companyLevel)\n        require(contractAccess.allowed) { contractAccess.reason }'
    );
  }
  // Complete manual: respeita resultado idempotente e consome ferramenta apenas quando houve liquidação nova.
  const range = functionBodyRange(out, 'completeContract');
  if (range) {
    let body = out.slice(range.open, range.close);
    if (!body.includes('val rewardPaid = contractDao.settleReward(')) {
      body = body.replace('contractDao.settleReward(', 'val rewardPaid = contractDao.settleReward(');
      body = body.replace(
        /\n(\s*)val latestCompany/,
        '\n$1if (rewardPaid) expansionRepository.consumeBoundTool(current.id)\n$1val latestCompany'
      );
      out = out.slice(0, range.open) + body + out.slice(range.close);
    }
  }
  return out;
}
function patchGradle(src) {
  const deps = [
    'implementation("androidx.credentials:credentials:1.3.0")',
    'implementation("androidx.credentials:credentials-play-services-auth:1.3.0")',
    'implementation("com.google.android.libraries.identity.googleid:googleid:1.1.1")',
  ];
  let out = src;
  const anchor = 'implementation("com.google.firebase:firebase-auth")';
  if (out.includes(anchor)) {
    let insert = '';
    for (const dep of deps) if (!out.includes(dep)) insert += '\n    ' + dep;
    if (insert) out = out.replace(anchor, anchor + insert);
  } else {
    const pos = out.lastIndexOf('}');
    if (pos >= 0) out = out.slice(0, pos) + '\n    // Google Credential Manager\n    ' + deps.join('\n    ') + '\n' + out.slice(pos);
  }
  return out;
}
function patchFirestoreRules(src) {
  if (src.includes('EXPANSION_CHARACTER_MARKET')) return src;
  const marker = '\n    // EXPANSION_CHARACTER_MARKET\n' +
`    match /character_offers/{ownerId} {
      allow read: if request.auth != null;
      allow create, delete: if request.auth != null && request.auth.uid == ownerId;
      allow update: if request.auth != null && (
        request.auth.uid == ownerId ||
        (
          request.resource.data.diff(resource.data).affectedKeys().hasOnly(['leasedBy', 'leasedUntil']) &&
          request.resource.data.leasedBy == request.auth.uid &&
          resource.data.leasedUntil <= request.time &&
          request.resource.data.leasedUntil > request.time
        )
      );
    }
    match /character_rentals/{rentalId} {
      allow create: if request.auth != null && request.resource.data.renterUid == request.auth.uid;
      allow read: if request.auth != null && (resource.data.renterUid == request.auth.uid || resource.data.ownerUid == request.auth.uid);
      allow update, delete: if false;
    }
`;
  const dbMatch = src.indexOf('match /databases/{database}/documents');
  if (dbMatch < 0) return src + '\n' + marker;
  const open = src.indexOf('{', dbMatch);
  const close = matchingBrace(src, open);
  if (close < 0) return src;
  return src.slice(0, close) + marker + src.slice(close);
}
function restore() {
  if (!fs.existsSync(MANIFEST)) throw new Error('Nenhum backup desta fix foi encontrado.');
  loadManifest();
  for (const relPath of manifest.created || []) {
    const full = path.join(ROOT, relPath);
    if (fs.existsSync(full)) { log('removendo criado:', relPath); if (!DRY_RUN) fs.rmSync(full, { force: true }); }
  }
  for (const relPath of manifest.modified || []) {
    const backupPath = path.join(BACKUP_DIR, relPath);
    if (!fs.existsSync(backupPath)) continue;
    log('restaurando:', relPath);
    if (!DRY_RUN) { fs.mkdirSync(path.dirname(path.join(ROOT, relPath)), { recursive: true }); fs.copyFileSync(backupPath, path.join(ROOT, relPath)); }
  }
  log('Restauração concluída.');
}

